import random
from collections import Counter

ok0 = ok1 = True
for _ in range(10000):
    M = [random.randint(-5, 5) for _ in range(random.randint(0, 10))]
    if M:
        p = random.randrange(len(M))
        v = random.randint(-5, 5)
        M2 = M[:p] + [v] + M[p+1:]
        for x in range(-6, 7):
            # Lemma 0: occ(x, M[p:=v]) = occ(x, M) + [v=x] - [M[p]=x]
            if Counter(M2)[x] != Counter(M)[x] + (v == x) - (M[p] == x):
                ok0 = False
    w = random.randint(-5, 5)
    M3 = M + [w]
    for x in range(-6, 7):
        # Lemma 1 (append): occ(x, M ++ [w]) = occ(x, M) + [w=x]
        if Counter(M3)[x] != Counter(M)[x] + (w == x):
            ok1 = False
print("Lemma 0 (update rule):", "holds" if ok0 else "VIOLATED")
print("Lemma 1 (append rule):", "holds" if ok1 else "VIOLATED")
EOF"}

